SELECT template_id, tag_code FROM learn_task_template_tag WHERE template_id IN
#{templateId}
ORDER BY template_id ASC, id ASC

SELECT CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM learn_task_template
WHERE owner_scope_key = #{ownerScopeKey}
  AND active_name_key = #{templateName}

SELECT CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM learn_task_template
WHERE owner_scope_key = #{ownerScopeKey}
  AND active_name_key = #{templateName}
  AND id <> #{excludedId}

mapper.update:
UPDATE learn_task_template
SET sort_order = #{sortOrder}, updated_by_user_id = #{ownerUserId},
    version_no = version_no + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND owner_user_id = #{ownerUserId}
  AND template_scope = 'PERSONAL' AND status = 'ENABLED'
  AND version_no = #{expectedVersion}
